parameters.jsCode:
// The Error Trigger payload contains:
//   - execution.id, execution.url
//   - workflow.name, workflow.id
//   - trigger.<details>
//   - lastNodeExecuted (name of the node that errored)
//   - executionMode (manual / trigger / etc)
// Pull a Slack-friendly summary.
const payload = $input.first().json;
const config = $('Config').first().json;

const workflowName = payload?.workflow?.name || '(unknown workflow)';
const workflowId = payload?.workflow?.id || '';
const execId = payload?.execution?.id || '';
const execUrl = payload?.execution?.url || '';
const lastNode = payload?.execution?.lastNodeExecuted || '(unknown node)';
const errorMessage = payload?.execution?.error?.message || payload?.execution?.error?.description || '(no message)';
const errorStack = payload?.execution?.error?.stack || '';

// Trim stack to first 6 lines so Slack stays scannable.
const stackPreview = errorStack.split('\n').slice(0, 6).join('\n');

return [{ json: {
  ...config,
  workflowName,
  workflowId,
  execId,
  execUrl,
  lastNode,
  errorMessage,
  stackPreview,
}}];

parameters.body:
={{ JSON.stringify({ text: `⚠️ *n8n workflow failure: ${$json.workflowName}*
Node that errored: \`${$json.lastNode}\`
Error: ${$json.errorMessage}
${$json.execUrl ? `<${$json.execUrl}|Open execution in n8n>` : `Execution ID: ${$json.execId}`}

\`\`\`${$json.stackPreview}\`\`\`` }) }}
